                        s1 = s2;
                        s2 = c0x * s1 + 4 * b10 * s0;
                        _gx[160] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 5 * b10 * s0;
                        _gx[192] = s2;
                        double xlxk = rlrk[n*32];
                        double Rqc = xlxk * al_akl;
                        double cpx = Rqc + rt_akl * Rpq[n*32];
                        s0 = _gx[0];
                        s1 = cpx * s0;
                        _gx[480] = s1;
                        s0 = _gx[32];
                        s1 = cpx * s0;
                        s1 += 1 * b00 * _gx[0];
                        _gx[512] = s1;
                        s0 = _gx[64];
                        s1 = cpx * s0;
                        s1 += 2 * b00 * _gx[32];
                        _gx[544] = s1;
                        s0 = _gx[96];
                        s1 = cpx * s0;
                        s1 += 3 * b00 * _gx[64];
                        _gx[576] = s1;
                        s0 = _gx[128];
                        s1 = cpx * s0;
                        s1 += 4 * b00 * _gx[96];
                        _gx[608] = s1;
                        s0 = _gx[160];
                        s1 = cpx * s0;
                        s1 += 5 * b00 * _gx[128];
                        _gx[640] = s1;
                        s0 = _gx[192];
                        s1 = cpx * s0;
                        s1 += 6 * b00 * _gx[160];
                        _gx[672] = s1;
                        s1 = _gx[192];
                        s0 = _gx[160];
                        _gx[320] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[128];
                        _gx[288] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[96];
                        _gx[256] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[64];
                        _gx[224] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[32];
                        _gx[192] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[0];
                        _gx[160] = s1 - xjxi * s0;
                        s1 = s0;
                        s1 = _gx[320];
                        s0 = _gx[288];
                        _gx[448] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[256];
                        _gx[416] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[224];
                        _gx[384] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[192];
                        _gx[352] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[160];
                        _gx[320] = s1 - xjxi * s0;
                        s1 = s0;
                        s1 = _gx[672];
                        s0 = _gx[640];
                        _gx[800] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[608];
                        _gx[768] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[576];
                        _gx[736] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[544];
                        _gx[704] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[512];
                        _gx[672] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[480];
                        _gx[640] = s1 - xjxi * s0;
                        s1 = s0;
                        s1 = _gx[800];
                        s0 = _gx[768];
                        _gx[928] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[736];
                        _gx[896] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[704];
                        _gx[864] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[672];
                        _gx[832] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[640];
                        _gx[800] = s1 - xjxi * s0;
                        s1 = s0;
                    }
                    __syncthreads();
                    double s;
                    volatile double *vgx = gx;
                    switch (gout_id) {
                    case 0:
                    s = dd_cache[1152] * (vgx[1376] * vgx[1920]);
                    s += dd_cache[1184] * (vgx[1344] * vgx[1952]);
                    s += dd_cache[1216] * (vgx[1312] * vgx[1984]);
                    s += dd_cache[1248] * (vgx[1280] * vgx[2016]);
                    s += dd_cache[1472] * (vgx[1216] * vgx[2080]);
                    s += dd_cache[1504] * (vgx[1184] * vgx[2112]);
                    s += dd_cache[1536] * (vgx[1152] * vgx[2144]);
                    s += dd_cache[1568] * (vgx[1120] * vgx[2176]);
                    s += dd_cache[1792] * (vgx[1056] * vgx[2240]);
                    s += dd_cache[1824] * (vgx[1024] * vgx[2272]);
                    s += dd_cache[1856] * (vgx[992] * vgx[2304]);
                    s += dd_cache[1888] * (vgx[960] * vgx[2336]);
                    v_ix += (ai2 * vgx[32]) * s;
                    v_jx += (aj2 * (vgx[32] - xjxi * vgx[0])) * s;
                    v_kx += (ak2 * vgx[480]) * s;
                    v_lx += (al2 * (vgx[480] - xlxk * vgx[0])) * s;
                    s = dd_cache[0] * (vgx[416] * vgx[1920]);
                    s += dd_cache[64] * (vgx[384] * vgx[1952]);
                    s += dd_cache[160] * (vgx[352] * vgx[1984]);
                    s += dd_cache[288] * (vgx[320] * vgx[2016]);
                    s += dd_cache[640] * (vgx[256] * vgx[2080]);
                    s += dd_cache[704] * (vgx[224] * vgx[2112]);
                    s += dd_cache[800] * (vgx[192] * vgx[2144]);
                    s += dd_cache[928] * (vgx[160] * vgx[2176]);
                    s += dd_cache[1600] * (vgx[96] * vgx[2240]);
                    s += dd_cache[1664] * (vgx[64] * vgx[2272]);
                    s += dd_cache[1760] * (vgx[32] * vgx[2304]);
                    s += dd_cache[1888] * (vgx[0] * vgx[2336]);
                    v_iy += (ai2 * vgx[992]) * s;
                    v_jy += (aj2 * (vgx[992] - yjyi * vgx[960])) * s;
                    v_ky += (ak2 * vgx[1440]) * s;
                    v_ly += (al2 * (vgx[1440] - ylyk * vgx[960])) * s;
                    s = dd_cache[0] * (vgx[416] * vgx[960]);
                    s += dd_cache[32] * (vgx[384] * vgx[992]);
                    s += dd_cache[96] * (vgx[352] * vgx[1024]);
