                    v_jz += (aj2 * (vgx[1952] - zjzi * vgx[1920])) * s;
                    v_kz += (ak2 * vgx[2400]) * s;
                    v_lz += (al2 * (vgx[2400] - zlzk * vgx[1920])) * s;
                    break;
                    case 1:
                    s = dd_cache[512] * (vgx[1216] * vgx[1920]);
