    if (t_id < 3) {
        int ri_ptr = bas[ish*BAS_SLOTS+PTR_BAS_COORD];
        int rj_ptr = bas[jsh*BAS_SLOTS+PTR_BAS_COORD];
        ri[t_id] = env[ri_ptr+t_id];
        rjri[t_id] = env[rj_ptr+t_id] - ri[t_id];
    }
    __syncthreads();
    double *ci = env + bas[ish*BAS_SLOTS+PTR_COEFF];
    double *cj = env + bas[jsh*BAS_SLOTS+PTR_COEFF];
    double xjxi = rjri[0];
    double yjyi = rjri[1];
    double zjzi = rjri[2];
    for (int ij = t_id; ij < iprim*jprim; ij += threads) {
        int ip = ij / jprim;
        int jp = ij % jprim;
        double ai = env[expi+ip];
        double aj = env[expj+jp];
        double aij = ai + aj;
        double theta_ij = ai * aj / aij;
        double rr_ij = xjxi*xjxi + yjyi*yjyi + zjzi*zjzi;
        double Kab = exp(-theta_ij * rr_ij);
        cicj_cache[ij] = ci[ip] * cj[jp] * Kab;
    }
    __syncthreads();

    int *ao_loc = envs.ao_loc;
    int nao = ao_loc[nbas];
    double *dm = jk.dm;
    double v_ix = 0;
    double v_iy = 0;
    double v_iz = 0;
    double v_jx = 0;
    double v_jy = 0;
    double v_jz = 0;
    for (int task_id = sq_id; task_id < ntasks+sq_id; task_id += nsq_per_block) {
        if (task_id >= ntasks) break;
        uint32_t bas_kl = bas_kl_idx[task_id];
        int ksh = bas_kl / nbas;
        int lsh = bas_kl % nbas;
        double fac_sym = PI_FAC;
        if (task_id < ntasks) {
            if (ish == jsh) fac_sym *= .5;
            if (ksh == lsh) fac_sym *= .5;
            if (ish*nbas+jsh == bas_kl) fac_sym *= .5;
        } else {
            fac_sym = 0;
        }
        int i0 = ao_loc[ish];
        int j0 = ao_loc[jsh];
        int k0 = ao_loc[ksh];
        int l0 = ao_loc[lsh];
        int expk = bas[ksh*BAS_SLOTS+PTR_EXP];
        int expl = bas[lsh*BAS_SLOTS+PTR_EXP];
        int ck = bas[ksh*BAS_SLOTS+PTR_COEFF];
        int cl = bas[lsh*BAS_SLOTS+PTR_COEFF];
        int rk = bas[ksh*BAS_SLOTS+PTR_BAS_COORD];
        int rl = bas[lsh*BAS_SLOTS+PTR_BAS_COORD];
        double xlxk = env[rl+0] - env[rk+0];
        double ylyk = env[rl+1] - env[rk+1];
        double zlzk = env[rl+2] - env[rk+2];
        double v_kx = 0;
        double v_ky = 0;
        double v_kz = 0;
        double v_lx = 0;
        double v_ly = 0;
        double v_lz = 0;
        int do_j = jk.j_factor != 0.;
        int do_k = jk.k_factor != 0.;
        double dd[9];
        if (jk.n_dm == 1) {
            double *dmb = dm;
            dd[0] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+0)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+0)]) : 0.) + (do_j ? jk.j_factor * dm[(j0+0)*nao+(i0+0)] * dm[(l0+0)*nao+(k0+0)] : 0.));
            dd[1] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+1)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+1)]) : 0.) + (do_j ? jk.j_factor * dm[(j0+0)*nao+(i0+1)] * dm[(l0+0)*nao+(k0+0)] : 0.));
            dd[2] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+2)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+2)]) : 0.) + (do_j ? jk.j_factor * dm[(j0+0)*nao+(i0+2)] * dm[(l0+0)*nao+(k0+0)] : 0.));
            dd[3] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+1)] * dm[(l0+0)*nao+(i0+0)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+1)*nao+(i0+0)]) : 0.) + (do_j ? jk.j_factor * dm[(j0+0)*nao+(i0+0)] * dm[(l0+0)*nao+(k0+1)] : 0.));
            dd[4] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+1)] * dm[(l0+0)*nao+(i0+1)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+1)*nao+(i0+1)]) : 0.) + (do_j ? jk.j_factor * dm[(j0+0)*nao+(i0+1)] * dm[(l0+0)*nao+(k0+1)] : 0.));
            dd[5] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+1)] * dm[(l0+0)*nao+(i0+2)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+1)*nao+(i0+2)]) : 0.) + (do_j ? jk.j_factor * dm[(j0+0)*nao+(i0+2)] * dm[(l0+0)*nao+(k0+1)] : 0.));
            dd[6] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+2)] * dm[(l0+0)*nao+(i0+0)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+2)*nao+(i0+0)]) : 0.) + (do_j ? jk.j_factor * dm[(j0+0)*nao+(i0+0)] * dm[(l0+0)*nao+(k0+2)] : 0.));
            dd[7] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+2)] * dm[(l0+0)*nao+(i0+1)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+2)*nao+(i0+1)]) : 0.) + (do_j ? jk.j_factor * dm[(j0+0)*nao+(i0+1)] * dm[(l0+0)*nao+(k0+2)] : 0.));
            dd[8] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+2)] * dm[(l0+0)*nao+(i0+2)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+2)*nao+(i0+2)]) : 0.) + (do_j ? jk.j_factor * dm[(j0+0)*nao+(i0+2)] * dm[(l0+0)*nao+(k0+2)] : 0.));
        } else {
            double *dmb = dm + nao * nao;
            dd[0] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+0)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+0)] + dmb[(j0+0)*nao+(k0+0)] * dmb[(l0+0)*nao+(i0+0)] + dmb[(j0+0)*nao+(l0+0)] * dmb[(k0+0)*nao+(i0+0)]) : 0.) + (do_j ? jk.j_factor * (dm[(j0+0)*nao+(i0+0)] + dmb[(j0+0)*nao+(i0+0)]) * (dm[(l0+0)*nao+(k0+0)] + dmb[(l0+0)*nao+(k0+0)]) : 0.));
            dd[1] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+1)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+1)] + dmb[(j0+0)*nao+(k0+0)] * dmb[(l0+0)*nao+(i0+1)] + dmb[(j0+0)*nao+(l0+0)] * dmb[(k0+0)*nao+(i0+1)]) : 0.) + (do_j ? jk.j_factor * (dm[(j0+0)*nao+(i0+1)] + dmb[(j0+0)*nao+(i0+1)]) * (dm[(l0+0)*nao+(k0+0)] + dmb[(l0+0)*nao+(k0+0)]) : 0.));
            dd[2] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+2)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+2)] + dmb[(j0+0)*nao+(k0+0)] * dmb[(l0+0)*nao+(i0+2)] + dmb[(j0+0)*nao+(l0+0)] * dmb[(k0+0)*nao+(i0+2)]) : 0.) + (do_j ? jk.j_factor * (dm[(j0+0)*nao+(i0+2)] + dmb[(j0+0)*nao+(i0+2)]) * (dm[(l0+0)*nao+(k0+0)] + dmb[(l0+0)*nao+(k0+0)]) : 0.));
            dd[3] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+1)] * dm[(l0+0)*nao+(i0+0)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+1)*nao+(i0+0)] + dmb[(j0+0)*nao+(k0+1)] * dmb[(l0+0)*nao+(i0+0)] + dmb[(j0+0)*nao+(l0+0)] * dmb[(k0+1)*nao+(i0+0)]) : 0.) + (do_j ? jk.j_factor * (dm[(j0+0)*nao+(i0+0)] + dmb[(j0+0)*nao+(i0+0)]) * (dm[(l0+0)*nao+(k0+1)] + dmb[(l0+0)*nao+(k0+1)]) : 0.));
            dd[4] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+1)] * dm[(l0+0)*nao+(i0+1)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+1)*nao+(i0+1)] + dmb[(j0+0)*nao+(k0+1)] * dmb[(l0+0)*nao+(i0+1)] + dmb[(j0+0)*nao+(l0+0)] * dmb[(k0+1)*nao+(i0+1)]) : 0.) + (do_j ? jk.j_factor * (dm[(j0+0)*nao+(i0+1)] + dmb[(j0+0)*nao+(i0+1)]) * (dm[(l0+0)*nao+(k0+1)] + dmb[(l0+0)*nao+(k0+1)]) : 0.));
            dd[5] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+1)] * dm[(l0+0)*nao+(i0+2)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+1)*nao+(i0+2)] + dmb[(j0+0)*nao+(k0+1)] * dmb[(l0+0)*nao+(i0+2)] + dmb[(j0+0)*nao+(l0+0)] * dmb[(k0+1)*nao+(i0+2)]) : 0.) + (do_j ? jk.j_factor * (dm[(j0+0)*nao+(i0+2)] + dmb[(j0+0)*nao+(i0+2)]) * (dm[(l0+0)*nao+(k0+1)] + dmb[(l0+0)*nao+(k0+1)]) : 0.));
            dd[6] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+2)] * dm[(l0+0)*nao+(i0+0)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+2)*nao+(i0+0)] + dmb[(j0+0)*nao+(k0+2)] * dmb[(l0+0)*nao+(i0+0)] + dmb[(j0+0)*nao+(l0+0)] * dmb[(k0+2)*nao+(i0+0)]) : 0.) + (do_j ? jk.j_factor * (dm[(j0+0)*nao+(i0+0)] + dmb[(j0+0)*nao+(i0+0)]) * (dm[(l0+0)*nao+(k0+2)] + dmb[(l0+0)*nao+(k0+2)]) : 0.));
            dd[7] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+2)] * dm[(l0+0)*nao+(i0+1)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+2)*nao+(i0+1)] + dmb[(j0+0)*nao+(k0+2)] * dmb[(l0+0)*nao+(i0+1)] + dmb[(j0+0)*nao+(l0+0)] * dmb[(k0+2)*nao+(i0+1)]) : 0.) + (do_j ? jk.j_factor * (dm[(j0+0)*nao+(i0+1)] + dmb[(j0+0)*nao+(i0+1)]) * (dm[(l0+0)*nao+(k0+2)] + dmb[(l0+0)*nao+(k0+2)]) : 0.));
            dd[8] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+2)] * dm[(l0+0)*nao+(i0+2)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+2)*nao+(i0+2)] + dmb[(j0+0)*nao+(k0+2)] * dmb[(l0+0)*nao+(i0+2)] + dmb[(j0+0)*nao+(l0+0)] * dmb[(k0+2)*nao+(i0+2)]) : 0.) + (do_j ? jk.j_factor * (dm[(j0+0)*nao+(i0+2)] + dmb[(j0+0)*nao+(i0+2)]) * (dm[(l0+0)*nao+(k0+2)] + dmb[(l0+0)*nao+(k0+2)]) : 0.));
        }
        for (int klp = 0; klp < kprim*lprim; ++klp) {
            int kp = klp / lprim;
            int lp = klp % lprim;
            double ak = env[expk+kp];
            double al = env[expl+lp];
            double ak2 = ak * 2;
            double al2 = al * 2;
            double akl = ak + al;
            double al_akl = al / akl;
            double theta_kl = ak * al_akl;
            double Kcd = exp(-theta_kl * (xlxk*xlxk+ylyk*ylyk+zlzk*zlzk));
            double ckcl = env[ck+kp] * env[cl+lp] * Kcd;
            if (fabs(ckcl) < PRIM_CUTOFF) continue;
            for (int ijp = 0; ijp < iprim*jprim; ++ijp) {
                int ip = ijp / jprim;
                int jp = ijp % jprim;
                double ai = env[expi+ip];
                double aj = env[expj+jp];
                double ai2 = ai * 2;
                double aj2 = aj * 2;
                double aij = ai + aj;
                double aj_aij = aj / aij;
                double cicj = cicj_cache[ijp];
                if (fabs(cicj) < PRIM_CUTOFF) continue;
                double fac = cicj * ckcl / (aij*akl*sqrt(aij+akl));
                double xij = ri[0] + rjri[0] * aj_aij;
                double yij = ri[1] + rjri[1] * aj_aij;
                double zij = ri[2] + rjri[2] * aj_aij;
                double xkl = env[rk+0] + xlxk * al_akl;
                double ykl = env[rk+1] + ylyk * al_akl;
                double zkl = env[rk+2] + zlzk * al_akl;
                double Rpq[3] = {xij - xkl, yij - ykl, zij - zkl};
                double rlrk[3] = {xlxk, ylyk, zlzk};
                double rr = Rpq[0]*Rpq[0] + Rpq[1]*Rpq[1] + Rpq[2]*Rpq[2];
                double theta = aij * akl / (aij + akl);
                rys_roots_for_k(nroots, theta, rr, rw, jk.omega, jk.lr_factor, jk.sr_factor, nsq_per_block, 1, 0);
                for (int irys = 0; irys < nroots; ++irys) {
                    double s0, s1, s2;
                    double rt = rw[irys*256];
                    double rt_aa = rt / (aij + akl);
                    double rt_aij = rt_aa * akl;
                    double rt_akl = rt_aa * aij;
                    double b10 = .5/aij * (1 - rt_aij);
                    double b00 = .5 * rt_aa;
                    double b01 = .5/akl * (1 - rt_akl);
                    double g[27];
                    g[0] = 1.;
                    g[9] = 1.;
                    g[18] = rw[irys*256+128] * fac;
                    {
                        constexpr int n = 0;
                        double *_gx = g + 0;
                        double xjxi = rjri[n];
                        double Rpa = xjxi * aj_aij;
                        double c0x = Rpa - rt_aij * Rpq[n];
                        s0 = _gx[0];
                        s1 = c0x * s0;
                        _gx[1] = s1;
                        s2 = c0x * s1 + 1 * b10 * s0;
                        _gx[2] = s2;
                        double xlxk = rlrk[n*1];
                        double Rqc = xlxk * al_akl;
                        double cpx = Rqc + rt_akl * Rpq[n*1];
                        s0 = _gx[0];
                        s1 = cpx * s0;
                        _gx[3] = s1;
                        s2 = cpx*s1 + 1 * b01 *s0;
                        _gx[6] = s2;
                        s0 = _gx[1];
                        s1 = cpx * s0;
                        s1 += 1 * b00 * _gx[0];
                        _gx[4] = s1;
                        s2 = cpx*s1 + 1 * b01 *s0;
                        s2 += 1 * b00 * _gx[3];
                        _gx[7] = s2;
                        s0 = _gx[2];
                        s1 = cpx * s0;
                        s1 += 2 * b00 * _gx[1];
                        _gx[5] = s1;
                        s2 = cpx*s1 + 1 * b01 *s0;
                        s2 += 2 * b00 * _gx[4];
                        _gx[8] = s2;
                    }
                    {
                        constexpr int n = 1;
                        double *_gx = g + 9;
                        double xjxi = rjri[n];
                        double Rpa = xjxi * aj_aij;
                        double c0x = Rpa - rt_aij * Rpq[n];
                        s0 = _gx[0];
                        s1 = c0x * s0;
                        _gx[1] = s1;
                        s2 = c0x * s1 + 1 * b10 * s0;
                        _gx[2] = s2;
                        double xlxk = rlrk[n*1];
                        double Rqc = xlxk * al_akl;
                        double cpx = Rqc + rt_akl * Rpq[n*1];
                        s0 = _gx[0];
                        s1 = cpx * s0;
                        _gx[3] = s1;
                        s2 = cpx*s1 + 1 * b01 *s0;
                        _gx[6] = s2;
                        s0 = _gx[1];
                        s1 = cpx * s0;
                        s1 += 1 * b00 * _gx[0];
                        _gx[4] = s1;
                        s2 = cpx*s1 + 1 * b01 *s0;
                        s2 += 1 * b00 * _gx[3];
                        _gx[7] = s2;
                        s0 = _gx[2];
                        s1 = cpx * s0;
                        s1 += 2 * b00 * _gx[1];
                        _gx[5] = s1;
                        s2 = cpx*s1 + 1 * b01 *s0;
                        s2 += 2 * b00 * _gx[4];
                        _gx[8] = s2;
                    }
                    {
                        constexpr int n = 2;
                        double *_gx = g + 18;
                        double xjxi = rjri[n];
                        double Rpa = xjxi * aj_aij;
                        double c0x = Rpa - rt_aij * Rpq[n];
                        s0 = _gx[0];
                        s1 = c0x * s0;
                        _gx[1] = s1;
                        s2 = c0x * s1 + 1 * b10 * s0;
                        _gx[2] = s2;
                        double xlxk = rlrk[n*1];
                        double Rqc = xlxk * al_akl;
                        double cpx = Rqc + rt_akl * Rpq[n*1];
                        s0 = _gx[0];
                        s1 = cpx * s0;
                        _gx[3] = s1;
                        s2 = cpx*s1 + 1 * b01 *s0;
                        _gx[6] = s2;
                        s0 = _gx[1];
                        s1 = cpx * s0;
                        s1 += 1 * b00 * _gx[0];
                        _gx[4] = s1;
                        s2 = cpx*s1 + 1 * b01 *s0;
                        s2 += 1 * b00 * _gx[3];
                        _gx[7] = s2;
                        s0 = _gx[2];
                        s1 = cpx * s0;
                        s1 += 2 * b00 * _gx[1];
                        _gx[5] = s1;
                        s2 = cpx*s1 + 1 * b01 *s0;
                        s2 += 2 * b00 * _gx[4];
                        _gx[8] = s2;
                    }
                    double s;
                    s = dd[4] * (g[13] * g[18]);
                    s += dd[5] * (g[12] * g[19]);
                    s += dd[7] * (g[10] * g[21]);
                    s += dd[8] * (g[9] * g[22]);
                    v_ix += (ai2 * g[1]) * s;
                    v_jx += (aj2 * (g[1] - xjxi * g[0])) * s;
                    v_kx += (ak2 * g[3]) * s;
                    v_lx += (al2 * (g[3] - xlxk * g[0])) * s;
                    s = dd[1] * (g[10] * g[18]);
                    s += dd[2] * (g[9] * g[19]);
                    v_ix += (ai2 * g[4]) * s;
                    v_jx += (aj2 * (g[4] - xjxi * g[3])) * s;
                    v_kx += (ak2 * g[6] - 1 * g[0]) * s;
                    v_lx += (al2 * (g[6] - xlxk * g[3])) * s;
                    s = dd[3] * (g[12] * g[18]);
                    s += dd[6] * (g[9] * g[21]);
                    v_ix += (ai2 * g[2] - 1 * g[0]) * s;
                    v_jx += (aj2 * (g[2] - xjxi * g[1])) * s;
                    v_kx += (ak2 * g[4]) * s;
                    v_lx += (al2 * (g[4] - xlxk * g[1])) * s;
                    s = dd[0] * (g[9] * g[18]);
                    v_ix += (ai2 * g[5] - 1 * g[3]) * s;
                    v_jx += (aj2 * (g[5] - xjxi * g[4])) * s;
                    v_kx += (ak2 * g[7] - 1 * g[1]) * s;
                    v_lx += (al2 * (g[7] - xlxk * g[4])) * s;
                    s = dd[0] * (g[4] * g[18]);
                    s += dd[2] * (g[3] * g[19]);
                    s += dd[6] * (g[1] * g[21]);
                    s += dd[8] * (g[0] * g[22]);
                    v_iy += (ai2 * g[10]) * s;
                    v_jy += (aj2 * (g[10] - yjyi * g[9])) * s;
                    v_ky += (ak2 * g[12]) * s;
                    v_ly += (al2 * (g[12] - ylyk * g[9])) * s;
                    s = dd[3] * (g[1] * g[18]);
                    s += dd[5] * (g[0] * g[19]);
                    v_iy += (ai2 * g[13]) * s;
                    v_jy += (aj2 * (g[13] - yjyi * g[12])) * s;
                    v_ky += (ak2 * g[15] - 1 * g[9]) * s;
                    v_ly += (al2 * (g[15] - ylyk * g[12])) * s;
                    s = dd[1] * (g[3] * g[18]);
                    s += dd[7] * (g[0] * g[21]);
                    v_iy += (ai2 * g[11] - 1 * g[9]) * s;
                    v_jy += (aj2 * (g[11] - yjyi * g[10])) * s;
                    v_ky += (ak2 * g[13]) * s;
                    v_ly += (al2 * (g[13] - ylyk * g[10])) * s;
                    s = dd[4] * (g[0] * g[18]);
                    v_iy += (ai2 * g[14] - 1 * g[12]) * s;
                    v_jy += (aj2 * (g[14] - yjyi * g[13])) * s;
                    v_ky += (ak2 * g[16] - 1 * g[10]) * s;
                    v_ly += (al2 * (g[16] - ylyk * g[13])) * s;
                    s = dd[0] * (g[4] * g[9]);
                    s += dd[1] * (g[3] * g[10]);
                    s += dd[3] * (g[1] * g[12]);
                    s += dd[4] * (g[0] * g[13]);
                    v_iz += (ai2 * g[19]) * s;
                    v_jz += (aj2 * (g[19] - zjzi * g[18])) * s;
                    v_kz += (ak2 * g[21]) * s;
                    v_lz += (al2 * (g[21] - zlzk * g[18])) * s;
                    s = dd[6] * (g[1] * g[9]);
                    s += dd[7] * (g[0] * g[10]);
                    v_iz += (ai2 * g[22]) * s;
                    v_jz += (aj2 * (g[22] - zjzi * g[21])) * s;
                    v_kz += (ak2 * g[24] - 1 * g[18]) * s;
                    v_lz += (al2 * (g[24] - zlzk * g[21])) * s;
                    s = dd[2] * (g[3] * g[9]);
                    s += dd[5] * (g[0] * g[12]);
                    v_iz += (ai2 * g[20] - 1 * g[18]) * s;
                    v_jz += (aj2 * (g[20] - zjzi * g[19])) * s;
                    v_kz += (ak2 * g[22]) * s;
                    v_lz += (al2 * (g[22] - zlzk * g[19])) * s;
                    s = dd[8] * (g[0] * g[9]);
                    v_iz += (ai2 * g[23] - 1 * g[21]) * s;
                    v_jz += (aj2 * (g[23] - zjzi * g[22])) * s;
                    v_kz += (ak2 * g[25] - 1 * g[19]) * s;
                    v_lz += (al2 * (g[25] - zlzk * g[22])) * s;
                }
            }
        }
        if (task_id >= ntasks) {
            break;
        }
        int ka = bas[ksh*BAS_SLOTS+ATOM_OF];
        int la = bas[lsh*BAS_SLOTS+ATOM_OF];
        double *ejk = jk.ejk;
        atomicAdd(ejk+ka*3+0, v_kx);
        atomicAdd(ejk+ka*3+1, v_ky);
        atomicAdd(ejk+ka*3+2, v_kz);
        atomicAdd(ejk+la*3+0, v_lx);
        atomicAdd(ejk+la*3+1, v_ly);
        atomicAdd(ejk+la*3+2, v_lz);
    }
    int ia = bas[ish*BAS_SLOTS+ATOM_OF];
    int ja = bas[jsh*BAS_SLOTS+ATOM_OF];
    double *ejk = jk.ejk;
    atomicAdd(ejk+ia*3+0, v_ix);
    atomicAdd(ejk+ia*3+1, v_iy);
    atomicAdd(ejk+ia*3+2, v_iz);
    atomicAdd(ejk+ja*3+0, v_jx);
    atomicAdd(ejk+ja*3+1, v_jy);
    atomicAdd(ejk+ja*3+2, v_jz);
}
